  const recipes = [
    R('pepperPork', '二荆条青椒肉丝', 'main', 18, [['pork',240],['greenPepper',220],['oil',10],['soySauce',8],['ginger',5]], ['川味家常','微辣','蛋白质搭档'], '里脊提供蛋白质，二荆条带来脆感与青椒香；少油快炒也能吃到熟悉的川味。', '配燕麦米饭和一份绿叶菜；青椒辣度较高时选不辣主菜轮换。', ['里脊顺纹切丝，拌少量生抽；二荆条去蒂切丝，生熟刀板分开。','热锅用部分油将肉丝炒至熟透，盛起。','剩余油炒香姜丝和青椒，回锅肉丝翻匀；避免再重复加盐。'], '#c5967e'),
    R('kungPaoChicken', '少油宫保鸡丁', 'main', 22, [['chickenBreast',260],['cucumber',120],['carrot',100],['peanut',20],['oil',10],['soySauce',8],['vinegar',8],['douban',5],['ginger',5]], ['家常改良','微辣','含花生'], '鸡肉作为蛋白质主体，黄瓜与胡萝卜增加菜色，少量花生增加脆香。', '搭配黑米饭与清炒小白菜；已有花生和用油，配菜宜清淡。', ['鸡胸切丁，黄瓜、胡萝卜切小块；生抽和香醋调成碗汁。','少量油炒香姜与豆瓣，加入鸡丁炒至熟透。','加入胡萝卜炒软，再下黄瓜与碗汁，最后拌入熟花生；这是一款无额外糖的家常改良版。'], '#c59774'),
    R('lettucePork', '莴笋木耳炒肉', 'main', 20, [['pork',230],['lettuceStem',260],['woodEar',6],['oil',10],['soySauce',8],['garlic',6]], ['清脆家常','菌菇搭配','不辣'], '莴笋、木耳与里脊形成脆、弹、嫩的口感，荤素自然搭在一起。', '配米饭与蒜蓉菠菜；木耳按干品加入，提前冷藏泡发。', ['干木耳冷藏泡发后洗净，去根；莴笋去老皮切片，里脊切片。','少量油先将肉片炒至熟透，加入蒜末。','放入莴笋、木耳和生抽，翻炒至蔬菜与木耳熟透。'], '#a6b692'),
    R('potatoChicken', '土豆炖鸡腿肉', 'main', 32, [['chickenThigh',260],['potato',220],['carrot',120],['onion',80],['oil',8],['soySauce',10],['ginger',8]], ['一锅家常','温暖炖菜','含薯类'], '鸡腿肉与蔬菜组成温暖炖菜；土豆属于薯类主食，需要一起考虑主食比例。', '米饭适当留小一份，另配西兰花或绿叶菜；不要把土豆完全当普通蔬菜。', ['去皮去骨鸡腿切块，土豆、胡萝卜切块，洋葱切片。','少量油炒香姜与洋葱，鸡肉翻炒后加入生抽和适量水。','放入土豆、胡萝卜，加盖炖至鸡肉熟透、土豆软；收汁但不额外重调味。'], '#c4a077'),
    R('tomatoEgg', '家常番茄炒蛋', 'main', 15, [['egg',200],['tomato',350],['oil',10],['scallion',5],['salt',1]], ['酸甜家常','不辣','蛋类主菜'], '鸡蛋提供蛋白质，番茄提供自然酸甜；不加糖也能做出家常风味。', '配米饭和一份脆绿蔬菜；可在另一餐安排豆腐或禽肉轮换。', ['鸡蛋打散，番茄切块，小葱洗净切末。','用部分油炒蛋至凝固后盛起，剩余油炒软番茄。','蛋块回锅煮透，少量盐调味，撒小葱。'], '#d99a83'),
    R('garlicPork', '青蒜苗肉丝', 'main', 18, [['pork',230],['garlicSprout',240],['oil',10],['soySauce',8],['ginger',5]], ['蒜香家常','冬春友好','不辣'], '肉丝为主蛋白，青蒜苗增加清香与口感；搭配另一份蔬菜更完整。', '配黑米杂粮饭与蒸紫皮长茄，形成清脆和柔软的对比。', ['肉切丝，蒜苗白段与叶段分开放，姜切丝。','热锅少量油炒熟肉丝，加姜与蒜苗白段。','加入生抽，最后加入叶段炒熟，避免叶子久炒。'], '#a9b184'),
    R('tofuEggSteam', '嫩豆腐蒸蛋', 'main', 22, [['egg',150],['silkenTofu',300],['soySauce',6],['oil',3],['scallion',5]], ['温柔蒸菜','蛋豆搭配','不辣'], '鸡蛋和嫩豆腐共同提供蛋白质，细滑口感适合与清脆蔬菜搭配。', '配燕麦米饭和蒜蓉西兰花；蒸蛋与主食同样不能取代蔬菜。', ['鸡蛋打散，加适量温水；嫩豆腐切块放入浅蒸碗。','倒入蛋液，盖上盘子或耐热盖，中小火蒸至中心完全凝固。','淋少量生抽和油，撒小葱；确认蛋液熟透再食用。'], '#e4cd9b'),
    R('mushroomTofuPot', '香菇青菜豆腐煲', 'main', 25, [['firmTofu',400],['bokChoy',300],['shiitake',150],['oil',8],['soySauce',8],['ginger',5]], ['植物蛋白','一锅清鲜','不辣'], '老豆腐提供植物蛋白，香菇增加鲜味，小白菜增加绿叶蔬菜。', '配黑米饭；豆腐已作主菜，另一配菜可以选择黄瓜或蒸茄子。', ['老豆腐切块，香菇切片，小白菜洗净分梗叶。','少量油炒香姜与香菇，加入水、生抽和豆腐煮热。','先下菜梗再下菜叶，煮至熟透；不以浓汤宝替代鲜味。'], '#b2b28b'),
    R('homeStyleTofu', '家常豆瓣烧豆腐', 'main', 20, [['firmTofu',400],['greenPepper',120],['carrot',100],['douban',8],['oil',8],['garlic',8]], ['植物蛋白','川味微辣','免油炸'], '豆腐做主蛋白，用少量豆瓣提味；不经油炸仍能有川味层次。', '配米饭与蒜蓉小白菜；豆瓣已有咸味，不叠加大量盐。', ['老豆腐切块，二荆条切段，胡萝卜切薄片。','少量油炒香蒜末与豆瓣，加适量水，放入豆腐和胡萝卜。','煮至豆腐热透，再加青椒烧熟，轻推翻匀。'], '#c79e80'),
    R('mushroomChicken', '香菇蒸鸡腿肉', 'main', 28, [['chickenThigh',280],['shiitake',180],['soySauce',8],['ginger',8],['scallion',5],['oil',4]], ['清鲜蒸菜','少油','不辣'], '鸡腿肉与鲜香菇蒸出自然鲜味，较少用油也有嫩滑口感。', '配燕麦饭与青椒胡萝卜；蒸汁可调味，不需额外重咸。', ['去皮去骨鸡腿切块，鲜香菇切片，姜切丝。','拌少量生抽和油，放入浅盘，铺姜丝与香菇。','蒸至鸡肉彻底熟透，检查最厚肉块，撒小葱。'], '#c1ad93'),
    R('cucumberChicken', '黄瓜木耳鸡丁', 'main', 20, [['chickenBreast',250],['cucumber',240],['woodEar',6],['oil',10],['soySauce',8],['ginger',5]], ['清脆快炒','不辣','菌菇搭配'], '鸡丁、黄瓜和木耳组成清脆的一餐主菜，用口感变化丰富日常饮食。', '配米饭与番茄炒小白菜；木耳提前冷藏泡发并煮熟。', ['木耳冷藏泡发洗净，鸡胸切丁，黄瓜切块。','少量油炒香姜，鸡丁下锅炒至熟透。','加入木耳炒熟，最后下黄瓜、生抽快速炒匀。'], '#aebf96'),
    R('onionPork', '洋葱青椒炒里脊', 'main', 18, [['pork',230],['onion',180],['greenPepper',150],['oil',10],['soySauce',8],['garlic',5]], ['甜香家常','微辣','快手'], '洋葱炒软的甜味与二荆条香气衬托里脊，不靠额外糖调味。', '配黑米饭和凉拌黄瓜；二荆条辣度随批次变化。', ['里脊切片，紫皮洋葱切丝，青椒去蒂切段。','少量油炒熟里脊，盛起；加入洋葱和蒜末炒软。','放入青椒炒熟，回锅肉片并加生抽拌匀。'], '#c2a294'),
    R('tomatoTofuEgg', '番茄豆腐烩蛋', 'main', 20, [['silkenTofu',300],['egg',150],['tomato',300],['oil',6],['salt',1],['scallion',5]], ['蛋豆搭配','酸甜温暖','不辣'], '嫩豆腐与鸡蛋共同提供蛋白质，番茄带来温暖酸甜。', '配米饭和清炒莴笋；有汤汁但仍把蛋与豆腐吃下。', ['番茄切块，嫩豆腐切小块，鸡蛋打散。','少量油将番茄炒软，加少量水与嫩豆腐煮开。','淋入蛋液并煮至完全凝固，少量盐调味，撒葱末。'], '#d7a18a'),
    R('lettuceChicken', '莴笋鸡片', 'main', 18, [['chickenBreast',250],['lettuceStem',280],['carrot',100],['oil',10],['soySauce',8],['ginger',5]], ['清鲜快炒','春日家常','不辣'], '莴笋与胡萝卜形成清脆配色，鸡片提供餐中的蛋白质。', '配燕麦米饭与蒜蓉菠菜，增加不同蔬菜种类。', ['鸡胸切薄片，莴笋去老皮切片，胡萝卜切薄片。','少量油炒熟鸡片，加入姜丝、胡萝卜翻炒。','加入莴笋与生抽炒至熟透，保留蔬菜清脆口感。'], '#afba94'),
    R('garlicTofu', '青蒜苗烧老豆腐', 'main', 20, [['firmTofu',400],['garlicSprout',220],['shiitake',100],['oil',8],['soySauce',8],['ginger',5]], ['植物蛋白','蒜香家常','不辣'], '老豆腐担当主蛋白，青蒜和香菇补足香气与口感。', '配黑米饭与凉拌黄瓜，主菜柔软、配菜清脆。', ['老豆腐切块，青蒜白段与叶段分开，香菇切片。','少量油炒香姜、香菇和蒜白，加适量水与生抽。','加入豆腐烧透，最后下蒜叶煮熟。'], '#b9b696'),

    R('garlicBroccoli', '蒜蓉西兰花', 'veg', 12, [['broccoli',450],['garlic',10],['oil',6],['salt',1]], ['清爽配菜','绿意搭配','不辣'], '增加蔬菜体积、花球口感与膳食纤维，让主菜更好搭配。', '与蛋、肉或豆腐主菜组合；它本身不能承担一餐的主蛋白。', ['西兰花掰小朵洗净，蒜切末。','沸水中短时焯至接近熟，沥水。','少量油炒香蒜末，加入西兰花与少量盐炒熟。'], '#9eb689'),
    R('stirBokChoy', '清炒小白菜', 'veg', 10, [['bokChoy',450],['garlic',8],['oil',6],['salt',1]], ['绿叶配菜','快手','不辣'], '用简单炒法增加绿叶蔬菜，适合搭配口味浓一些的川味主菜。', '搭配宫保鸡丁、家常豆腐和米饭。', ['小白菜逐片洗净，菜梗与菜叶分开。','少量油炒香蒜末，先下菜梗翻炒。','加入菜叶炒熟，少量盐调味，及时出锅。'], '#9aae7d'),
    R('garlicSpinach', '蒜蓉菠菜', 'veg', 12, [['spinach',450],['garlic',8],['oil',6],['salt',1]], ['深绿叶菜','家常清鲜','不辣'], '为一餐增加深绿叶菜与纤维；不同蔬菜轮换比只选一种更丰富。', '搭配莴笋木耳炒肉或嫩豆腐蒸蛋。', ['菠菜洗净去老根，蒜切末。','菠菜沸水焯后沥干。','少量油炒香蒜末，菠菜回锅快速炒熟，少量盐调味。'], '#91a779'),
    R('cucumberSalad', '香醋凉拌黄瓜', 'veg', 10, [['cucumber',450],['garlic',8],['vinegar',12],['soySauce',6],['oil',3]], ['清爽脆口','免开火','不辣'], '清脆黄瓜平衡蒸、煲类主菜的柔软口感，少量酸香即可提味。', '搭配豆腐煲与杂粮饭；凉菜现拌现吃。', ['黄瓜用安全水洗净，使用干净的即食菜刀板，拍开切块。','蒜末与香醋、生抽、少量油拌成汁。','食用前拌匀，避免常温久放。'], '#b4c49d', { storage: '凉拌后及时食用；需要暂存时密封冷藏，与生肉分开。本应用不建议作为隔夜备菜。' }),
    R('steamedEggplant', '蒜香蒸紫皮长茄', 'veg', 18, [['eggplant',450],['garlic',10],['soySauce',8],['vinegar',8],['oil',4],['scallion',5]], ['长茄限定','先蒸少油','不辣'], '先蒸软再调味，减少吸油，保留紫皮长茄柔软的质地。', '搭配蒜苗肉丝和黑米饭；与圆茄替换时口感需另调整。', ['紫皮长茄洗净，切长段或对半剖开。','蒸至彻底软熟，转入干净盘中。','蒜末、生抽、香醋和少量油拌匀，趁热浇汁撒葱。'], '#b69ab2'),
    R('pepperCarrot', '青椒胡萝卜丝', 'veg', 12, [['greenPepper',200],['carrot',250],['oil',6],['garlic',6],['salt',1]], ['双色配菜','微辣','清脆'], '青椒和胡萝卜增加不同颜色与口感，适合温和蒸菜旁的一份蔬菜。', '配香菇蒸鸡腿或嫩豆腐蒸蛋与米饭。', ['胡萝卜切细丝，二荆条去蒂切丝。','少量油炒香蒜，先下胡萝卜炒软。','加青椒炒至熟，少量盐调味。'], '#c4b184'),
    R('mushroomGreens', '香菇炒小白菜', 'veg', 15, [['bokChoy',350],['shiitake',150],['oil',6],['garlic',6],['soySauce',6]], ['绿叶菌菇','清鲜','不辣'], '香菇提供自然鲜味，小白菜增加绿叶蔬菜和清爽口感。', '配鸡肉或蛋类主菜与杂粮饭。', ['鲜香菇切片，小白菜洗净分梗叶。','少量油先炒香菇与蒜末，下菜梗。','加菜叶和生抽炒熟，不额外重复加盐。'], '#aca98b'),
    R('stirLettuce', '清炒莴笋片', 'veg', 12, [['lettuceStem',450],['garlic',6],['oil',6],['salt',1]], ['清脆茎菜','不辣','快手'], '莴笋清香与脆感可搭配柔软的豆腐、蒸蛋或炖菜。', '配番茄豆腐烩蛋或土豆炖鸡，另轮换一餐深绿叶菜。', ['青皮莴笋去老皮，切薄片。','少量油炒香蒜末，下莴笋片翻炒。','炒熟后少量盐调味，及时出锅。'], '#b6c6a0'),
    R('carrotWoodEar', '胡萝卜木耳小炒', 'veg', 15, [['carrot',300],['woodEar',8],['onion',100],['oil',6],['soySauce',6],['garlic',6]], ['菌菇配色','清脆','不辣'], '胡萝卜的甜味与木耳脆感丰富配菜，注意木耳干品与泡发后的区别。', '搭配蛋或豆腐主菜；需要主食和主蛋白共同组成一餐。', ['木耳冷藏泡发洗净，胡萝卜切薄片，洋葱切丝。','少量油炒香蒜与洋葱，加入胡萝卜炒软。','加入木耳与生抽，翻炒至木耳彻底熟透。'], '#c6a386'),
    R('tomatoGreens', '番茄炒小白菜', 'veg', 12, [['tomato',220],['bokChoy',300],['oil',6],['garlic',6],['salt',1]], ['红绿搭配','酸甜清鲜','不辣'], '番茄的自然酸味配上绿叶菜，增加菜单变化。', '搭配黄瓜木耳鸡丁与米饭，避免天天只吃同一种绿叶菜。', ['番茄切块，小白菜洗净分梗叶。','少量油炒香蒜，番茄下锅炒出汁。','加入菜梗和菜叶依次炒熟，少量盐调味。'], '#b5b095'),

    R('winterMelonPorkSoup', '冬瓜瘦肉汤', 'soup', 25, [['winterMelon',450],['pork',180],['ginger',8],['salt',1],['scallion',5]], ['清汤','含肉','不辣'], '冬瓜与瘦肉形成清淡汤菜；吃汤里的肉才能摄入主要的蛋白质。', '可与米饭、绿叶菜搭配；本库推荐餐仍另设主菜槽，不只喝汤代餐。', ['冬瓜去皮去瓤切片，里脊切薄片；生熟用具分开。','水煮开后下姜和冬瓜，煮至冬瓜软。','加入肉片煮至彻底熟透，少量盐与葱调味。'], '#c3c9ac'),
    R('tomatoTofuSoup', '番茄嫩豆腐汤', 'soup', 15, [['tomato',300],['silkenTofu',250],['oil',3],['salt',1],['scallion',5]], ['酸甜清汤','豆腐配角','不辣'], '番茄提供酸甜，嫩豆腐补充一些植物蛋白；它只是餐的搭档。', '搭配禽肉或蛋类主菜、米饭与绿叶菜。', ['番茄切块，嫩豆腐轻切块。','少量油炒软番茄，加水煮开。','加入豆腐煮透，少量盐调味，撒葱末。'], '#d2ac99'),
    R('spinachEggSoup', '菠菜蛋花汤', 'soup', 12, [['spinach',200],['egg',100],['ginger',3],['salt',1]], ['深绿汤菜','蛋花','不辣'], '汤菜增加温暖口感，蛋花与菠菜共同丰富餐的内容。', '搭配里脊或豆腐主菜和米饭；不把汤当蔬菜与蛋白质达标凭据。', ['菠菜洗净焯水，鸡蛋打散。','另锅清水加姜煮开，放入菠菜。','淋入蛋液，煮到蛋花完全凝固，少量盐调味。'], '#acb997'),
    R('mushroomWinterSoup', '香菇冬瓜清汤', 'soup', 20, [['shiitake',150],['winterMelon',400],['ginger',5],['salt',1],['scallion',5]], ['菌菇清汤','无主蛋白','不辣'], '香菇鲜味与冬瓜的柔软口感搭配，是正餐旁的清汤。', '必须搭配蛋、肉或豆腐主菜和主食；这道汤不能替代主菜。', ['冬瓜去皮去瓤切片，鲜香菇洗净切片。','清水加姜和香菇煮开，加入冬瓜。','煮至冬瓜软熟，少量盐调味并撒葱。'], '#c6c4ab'),
    R('cornChickenSoup', '玉米胡萝卜鸡汤', 'soup', 35, [['chickenThigh',200],['corn',150],['carrot',150],['ginger',8],['salt',1]], ['温暖汤菜','含谷薯','不辣'], '鸡肉、玉米和胡萝卜构成有内容的汤菜；玉米计入主食搭配。', '吃下鸡肉与玉米，配绿叶菜；根据玉米份额调整米饭。', ['去皮去骨鸡腿切块，鲜甜玉米剥粒，胡萝卜切块。','锅中加水、姜和鸡肉煮开，撇浮沫。','加入玉米和胡萝卜，炖至鸡肉熟透、蔬菜软，少量盐调味。'], '#d4be96'),

    R('whiteRice', '松软籼米饭', 'staple', 30, [['rice',140]], ['基础主食','米饭照常吃','不辣'], '米饭为一餐提供基础能量；与蔬菜及蛋白质一起搭配。', '配一道主菜与一道蔬菜，不因减脂就完全取消主食。', ['籼米快速淘洗，不反复揉搓。','按电饭煲与米种建议加水，使用煮饭程序。','煮好稍焖再翻松；需留存时及时分装冷藏。'], '#e2d5b9'),
    R('oatRice', '燕麦米饭', 'staple', 30, [['rice',100],['oats',40]], ['米饭杂粮搭档','全谷物','不辣'], '保留米饭熟悉的口感，加入原味燕麦增加全谷物与纤维。', '适合青椒肉丝、蒸蛋等主菜；杂粮比例可按耐受与口感逐步增加。', ['籼米淘洗，原味燕麦片按包装决定是否需冲洗。','加入燕麦片与适量水，使用煮饭程序。','煮熟后焖片刻、翻松；不加糖或奶精。'], '#d6c8a5'),
    R('blackRiceMix', '黑米杂粮饭', 'staple', 40, [['rice',100],['blackRice',40]], ['黑米搭配','全谷物','不辣'], '普通米饭搭配非糯性黑米，增加颗粒感与菜单变化。', '配香菇豆腐煲、蒜苗肉丝与绿叶菜；黑米仍是主食。', ['黑米洗净后按米种要求冷藏浸泡；籼米淘洗。','黑米与籼米一起入锅，按米种建议加水。','煮至米粒软熟并稍焖；制作时间不含提前浸泡。'], '#b1a0ab'),
    R('pumpkinOatCongee', '南瓜燕麦粥', 'staple', 25, [['pumpkin',200],['oats',70],['rice',40]], ['暖胃口感','全谷搭配','不加糖'], '老南瓜的自然甜味配燕麦；这是一道主食，不是一餐完整营养。', '配豆腐蒸蛋与青菜；稀粥不能代替一餐的蛋白质和蔬菜。', ['老南瓜去皮去籽切小块，籼米淘洗。','水中加入米和南瓜煮开，转小火煮软。','按燕麦片包装时长加入燕麦，煮至熟，不另加糖。'], '#dfba85'),
    R('cornOatCongee', '玉米燕麦粥', 'staple', 22, [['corn',160],['oats',80],['rice',30]], ['谷物轮换','清甜','不加糖'], '鲜甜玉米与燕麦增加不同主食口感，适合清爽晚餐组合。', '搭配蒸鸡、豆腐或鸡蛋主菜，另配足量蔬菜。', ['鲜甜玉米剥粒，籼米淘洗。','锅中加水、米与玉米粒，煮至米粒软。','加入原味燕麦片，按包装时长煮熟，不加糖。'], '#decc98'),
    R('potatoRice', '土豆焖饭', 'staple', 35, [['rice',100],['potato',180],['carrot',80]], ['谷薯组合','电饭煲友好','不辣'], '土豆与籼米同作主食，胡萝卜增加配色；土豆不是额外无限添加的配菜。', '搭配不含土豆的肉、蛋或豆腐主菜与绿叶菜。', ['黄心土豆去皮切小块，胡萝卜切丁，籼米淘洗。','食材一起放电饭煲，按米种与锅具建议加水。','煮至米饭和土豆完全熟，轻轻翻松。'], '#d5c09c'),
    R('cornRice', '玉米粒米饭', 'staple', 30, [['rice',110],['corn',150]], ['自然清甜','谷物轮换','不辣'], '鲜甜玉米粒增加米饭的甜香与口感；两者一起算主食。', '配蒜苗豆腐或番茄炒蛋与绿叶菜，少用重咸酱汁。', ['籼米淘洗，鲜甜玉米剥粒洗净。','按电饭煲建议加水，将玉米粒铺在米上。','煮熟后稍焖，轻轻翻匀。'], '#e1ce9a'),
    R('celeryPork', '芹菜肉丝', 'main', 18, [['pork',230],['celeryChinese',200],['carrot',60],['oil',8],['soySauce',8],['ginger',5]], ['细茎芹菜','清香家常','不辣'], '里脊提供蛋白质，细茎芹菜带来清香与脆感，胡萝卜增加配色。', '搭配黑米饭与清炒上海青；此处用中国芹菜，不按西芹等量混用。', ['里脊切细丝，细茎芹菜去老筋切段，胡萝卜切细丝；生熟刀板分开。','少量油炒香姜，肉丝下锅炒至完全熟透。','先加胡萝卜炒软，再加芹菜与生抽炒熟，避免重复重咸调味。'], '#b6b193'),
    R('gingerDuck', '仔姜鸭胸', 'main', 25, [['duckBreast',260],['tenderGinger',80],['greenPepper',150],['oil',8],['soySauce',8],['douban',5],['garlic',6],['ginger',4]], ['禽肉轮换','仔姜清香','川味微辣'], '去皮鸭胸增加禽肉轮换，仔姜与二荆条带来川渝家常香气。', '配燕麦饭与蒜蓉豌豆尖；豆瓣与生抽已有咸味，鸭肉充分熟制。', ['去皮无骨鸭胸切薄片，仔姜切薄片，二荆条切段，生熟用具分开。','少量油炒香老姜、蒜与豆瓣，下鸭片充分翻炒。','加入仔姜、青椒与少量水、生抽，烧至鸭片中心熟透；不要保留粉红夹生中心，使用温度计检查更可靠。'], '#b19f89', {safetySourceIds:['cfsCooking']}),
    R('radishChicken', '白萝卜炖鸡', 'main', 35, [['chickenThigh',240],['whiteRadish',320],['shiitake',100],['oil',6],['soySauce',8],['ginger',8]], ['清甜炖菜','一锅家常','不辣'], '去皮鸡腿肉搭配煮软的白萝卜与香菇，形成有肉有菜的温暖炖菜。', '配米饭和荷兰豆杏鲍菇；汤汁只是搭档，鸡肉与蔬菜都要吃。', ['去皮去骨鸡腿切小块，白萝卜去老皮切块，鲜香菇切片。','少量油炒香姜与鸡肉，加入适量水、生抽、萝卜和香菇。','煮开后小火炖至萝卜软、鸡肉完全熟透；检查较厚鸡块，不用颜色或固定分钟数代替熟度确认。'], '#c7c0a5', {safetySourceIds:['cfsCooking']}),
    R('lotusPork', '藕片炒里脊', 'main', 20, [['pork',220],['lotusRoot',220],['greenPepper',100],['oil',8],['soySauce',8],['garlic',6]], ['白花脆藕','微辣','口感轮换'], '熟里脊与带孔洞的脆藕片形成嫩脆搭配，二荆条增加川味香气。', '配燕麦饭和清炒大白菜；藕也含一定淀粉，不再搭土豆焖饭。', ['白花藕洗净去老皮切薄片，里脊切薄片，二荆条切段。','少量油将里脊炒至完全熟透，盛起；余油炒香蒜末。','加入藕片与少量水炒熟，再下青椒、肉片和生抽翻匀；保持熟脆口感。'], '#c9b99a'),
    R('luffaEgg', '丝瓜炒蛋', 'main', 15, [['egg',200],['luffa',300],['oil',8],['garlic',6],['salt',1]], ['柔嫩家常','蛋类主菜','不辣'], '丝瓜煮软的清甜配上凝固炒蛋，给蛋类主菜增加不同蔬菜质地。', '配黑米饭和彻底煮熟的蒜香四季豆；蛋与丝瓜均充分熟制。', ['嫩丝瓜去皮切滚刀块，鸡蛋打散，蒜切末。','用部分油把蛋炒至完全凝固后盛起，余油炒香蒜末。','加丝瓜与少量水焖至熟软，蛋块回锅热透，少量盐调味。'], '#d2bf93'),
    R('shrimpTofu', '河虾仁豆腐煲', 'main', 22, [['shrimp',220],['firmTofu',300],['shanghaiBok',150],['oil',6],['ginger',5],['soySauce',6]], ['虾豆搭配','植物与动物蛋白','不辣'], '河虾仁与老豆腐共同提供蛋白质，上海青补充蔬菜口感，薄汤汁让菜更温润。', '配玉米饭和西葫芦炒金针菇；对甲壳类过敏时不选这道菜。', ['鲜河虾仁按产品情况去残壳与虾线，老豆腐切块，上海青逐片洗净。','少量油炒香姜，加入适量水、生抽和豆腐煮透。','加入虾仁和上海青煮至虾肉完全不透明、菜熟；彻底加热，不只凭虾变色就提早出锅。'], '#c7bea4', {safetySourceIds:['cfsCooking']}),
    R('stirShanghaibok', '清炒上海青', 'veg', 12, [['shanghaiBok',320],['garlic',8],['oil',6],['salt',1]], ['厚梗绿叶','清爽配菜','不辣'], '上海青的厚梗与绿叶丰富蔬菜口感，适合搭配肉丝与豆腐主菜。', '配芹菜肉丝与杂粮饭；与青梗小白菜轮换，不混淆条目。', ['上海青去坏叶逐片洗净，大梗切短段，梗叶分开。','少量油炒香蒜末，先放厚梗炒熟。','再加叶片炒至熟软，少量盐调味，及时出锅。'], '#a8b58b'),
    R('garlicPeaTender', '蒜蓉豌豆尖', 'veg', 10, [['peaTender',260],['garlic',8],['oil',6],['salt',1]], ['冬春嫩梢','绿叶轮换','不辣'], '嫩叶、细茎与卷须组成清香绿叶配菜，增加菜单变化。', '配仔姜鸭胸与米饭；只用豌豆嫩梢，不以豆粒或豆荚替代。', ['豌豆尖去老梗，清水逐次洗净并沥水；蒜切末。','少量油炒香蒜末，加入豌豆尖翻炒。','炒至茎叶完全熟软，少量盐调味，不用生嫩外观代替熟度确认。'], '#acc191'),
    R('snowPeaMushroom', '荷兰豆杏鲍菇', 'veg', 16, [['snowPea',200],['kingOyster',160],['oil',6],['garlic',8],['soySauce',6]], ['豆荚菌菇','清脆弹嫩','不辣'], '熟荷兰豆荚与杏鲍菇薄片形成不同口感，让蔬菜种类更丰富。', '配白萝卜炖鸡或蒸蛋与米饭；豆荚和菌菇均炒熟。', ['荷兰豆去筋清洗，杏鲍菇切薄片，蒜切末。','荷兰豆先用沸水煮熟沥水；少量油炒香蒜与杏鲍菇片。','菌菇炒熟后加入荷兰豆、生抽翻匀，整体热透。'], '#b7bc9d'),
    R('stirNapa', '清炒大白菜', 'veg', 12, [['napaCabbage',360],['garlic',8],['oil',6],['salt',1]], ['清甜白菜','软嫩配菜','不辣'], '大白菜厚白梗与浅绿叶片熟软清甜，适合和脆藕或肉类主菜搭配。', '配藕片炒里脊与米饭，也可与深绿叶菜在不同餐轮换。', ['大白菜逐片清洗，白梗和叶片切短段并分开。','少量油炒香蒜末，白梗先入锅炒软。','加入叶片炒熟，少量盐调味，不添加配方外的蚝油或肉。'], '#c8cbad'),
    R('wellCookedGreenBean', '蒜香四季豆', 'veg', 22, [['greenBean',300],['garlic',8],['oil',6],['salt',1]], ['必须彻底煮熟','少油熟制','不辣'], '彻底煮熟的四季豆为餐中增加熟制豆荚与纤维；安全熟度优先于鲜绿颜色。', '搭配丝瓜炒蛋、米饭；不能生食、低温慢煮或仅焯数秒后快炒。', ['四季豆去两头与老筋，洗净切短斜段，蒜切末。','在足量沸水中持续煮至所有豆段完全熟透，避免锅内拥挤；不是短焯数秒。时间随豆段粗细变化，不能只凭颜色判断。','沥水后少量油炒香蒜末，四季豆回锅充分热透，少量盐调味；有硬生口感或未熟部分时继续煮，不尝生豆判断。'], '#a8ad7d', {safetySourceIds:['cfsBeans'],safetyNote:'四季豆务必彻底煮熟。干豆的浸泡与煮制方案不能机械套到鲜豆荚，也不能将固定炒制时长视为安全保证。'}),
    R('zucchiniMushroom', '西葫芦炒金针菇', 'veg', 15, [['zucchini',220],['enoki',150],['oil',6],['garlic',8],['soySauce',6]], ['柔嫩瓜菜','菌菇轮换','不辣'], '浅绿西葫芦片与细束金针菇搭配，增加熟蔬菜口感与菌菇种类。', '配河虾仁豆腐煲或鸡肉主菜与米饭；金针菇彻底煮熟。', ['嫩西葫芦洗净切半月薄片，金针菇去根洗净拆小束。','少量油炒香蒜末，先下西葫芦，再加金针菇与少量水。','煮炒至瓜片熟软、金针菇彻底熟透，加生抽翻匀，避免额外重咸调味。'], '#c2c6a7')
  ];

